CREATE OR REPLACE FUNCTION public.sandbox_follows_new_market()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.community_members (community_id, profile_id, role, status)
